import json
from collections import defaultdict
from pathlib import Path
root=Path("test-results/pr33824_expanded_all13_predictors_20260928_1933")
for name in ("Qwen3-0.6B","Qwen2.5-3B-Instruct","llama-2-7b"):
    groups=defaultdict(lambda: [0,0,0.0,0])
    for path in sorted((root/"models"/name/"holdout/real").glob("repeat-*/cases/*/TP0.schedule_batch.jsonl")):
        for line in path.read_text().splitlines():
            item=json.loads(line)
            if item["forward_mode"] not in (1,2):
                continue
            reqs=item["request_infos"]
            key=(path.parent.name,item["forward_mode"])
            groups[key][0]+=1
            inferred_decode=all(req["extend_input_len"]<=1 for req in reqs)
            if inferred_decode != (item["forward_mode"]==2):
                groups[key][1]+=1
                groups[key][2]+=item["iter_latency"]
                groups[key][3]+=sum(req["extend_input_len"]==0 for req in reqs)
    print(name, "mode mismatches",sum(value[1] for value in groups.values()),"of",sum(value[0] for value in groups.values()))
    for key,value in sorted(groups.items()):
        if value[1]:
            print(key,value,"mean mismatched ms",value[2]/value[1]*1000)
